CSS = """:root{--bg:#fff8ea;--fg:#3b2f2f;--muted:#7a6a5a;--line:rgba(90,60,30,.18);--link:#2f6fd0;--acc:#c77a10;color-scheme:light}
@media (prefers-color-scheme:dark){:root{--bg:#1b1d2a;--fg:#f2ede4;--muted:#b3a99a;--line:rgba(242,237,228,.2);--link:#8fc4ff;--acc:#ffd36b;color-scheme:dark}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.7 system-ui,-apple-system,'Segoe UI','PingFang TC','Hiragino Sans','Apple SD Gothic Neo','Noto Sans TC','Noto Sans JP','Noto Sans KR','Microsoft JhengHei',sans-serif}
main{max-width:720px;margin:0 auto;padding:24px 16px 56px}h1{font-size:26px;line-height:1.3;margin:8px 0 4px}
h2{font-size:19px;margin:32px 0 6px;padding-top:12px;border-top:1px solid var(--line)}p,li{margin:6px 0}ul{padding-left:1.3em}
.meta,.lang{color:var(--muted);font-size:14px}.lang a{margin-right:14px;display:inline-block}a{color:var(--link)}
.box{border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin:16px 0;background:rgba(255,211,107,.12)}.box b{color:var(--acc)}"""


def page(lang, title, body, prefix=''):
    links = ''.join(f'<a href="{prefix}{FILES[l] if FILES[l] != "index.html" else "./"}">{NAMES[l]}</a>' for l in FILES)
    return f'<!doctype html>\n<html lang="{HTML_LANG[lang]}">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>{html.escape(title)}</title>\n<meta name="description" content="{html.escape(title)}">\n<style>\n{CSS}\n</style>\n</head>\n<body>\n<main>\n<h1>{html.escape(title)}</h1>\n<p class="lang">{links}</p>\n{body}\n</main>\n</body>\n</html>\n'


os.makedirs(os.path.join(ROOT, 'privacy'), exist_ok=True); os.makedirs(os.path.join(ROOT, 'support'), exist_ok=True)
for lang, d in P.items():
    body = f'<p class="meta">{d["meta"].format(u=UPDATED[lang])}</p>\n<div class="box">{d["one"]}</div>\n' + '\n'.join(f'<h2>{h}</h2>\n{t.format(e=EMAIL)}' for h, t in d['s'])
    open(os.path.join(ROOT, 'privacy', FILES[lang]), 'w', encoding='utf-8').write(page(lang, d['title'], body))
# 支援頁：一頁五種語言（Apple 的 Support URL 只能填一個）
t0, _, _, _ = SUP['zh-Hant']
parts = []
for lang, (t, p, faq, priv) in SUP.items():
    pf = FILES[lang] if FILES[lang] != 'index.html' else ''
    parts.append(f'<section lang="{HTML_LANG[lang]}"><h2>{html.escape(t)}</h2><p>{p.format(e=EMAIL)}</p><ul>' + ''.join(f'<li>{html.escape(x)}</li>' for x in faq) + f'</ul><p><a href="../privacy/{pf}">{priv}</a></p></section>')
open(os.path.join(ROOT, 'support', 'index.html'), 'w', encoding='utf-8').write(page('zh-Hant', '滴答小鎮・Tick-Tock Town — Support', '\n'.join(parts), prefix='#').replace('<p class="lang">', '<p class="lang" hidden>'))
print('privacy:', ', '.join(FILES.values()), '+ support/index.html')
